import fs from 'node:fs';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createDocument} from 'file:///Users/fordeargamers/Projects/exoduser-migration-20261001/tools/team-followup-20261001/UIUX/inventory-dom/node-dom.mjs';
import {createHost} from 'file:///Users/fordeargamers/Projects/exoduser-migration-20261001/tools/team-followup-20261001/UIUX/card-removal-focus/host/harness.js';
import {extractFunction} from 'file:///Users/fordeargamers/Projects/exoduser-migration-20261001/tools/team-followup-20261001/UIUX/inventory-dom-candidate.mjs';
import {sourceFactory} from 'file:///Users/fordeargamers/Projects/exoduser-migration-20261001/tools/team-followup-20261001/UIUX/filter-focus-candidate.mjs';

const root=new URL('file:///Users/fordeargamers/Projects/exoduser-migration-20261001/'),sha=value=>createHash('sha256').update(value).digest('hex');
const composition=fs.readFileSync(new URL('ui-panels.js',root),'utf8');
const helpers=composition.slice(composition.indexOf('  const el ='),composition.indexOf('  function describeSettingsControls'));
const inventory=composition.slice(composition.indexOf('  function inventory()'),composition.indexOf('  function init()'));
assert.ok(helpers.includes('function tabBar(')&&inventory.includes("root.addEventListener('wheel'"),'현행 inventory composition 경계');
const sourceRecords={},results=[],startedAt=new Date().toISOString();
const candidate=process.argv.includes('--candidate');
const guardPrefix="if(['Space','Enter','NumpadEnter','Tab'].includes(e.code)&&e.target instanceof Element";
const guardCandidate="if(['Space','Enter','NumpadEnter','Tab'].includes(e.code)&&(e.defaultPrevented||e.target instanceof Element";
function patched(source) {
  assert.equal(source.split(guardPrefix).length,2,'한 파일의 유일한 panel guard');
  const guard=source.split('\n').find(line=>line.includes(guardPrefix));
  const changed=guard.replace(guardPrefix,guardCandidate).replace("#settings.on select'))return;","#settings.on select')))return;");
  assert.notEqual(changed,guard);return source.replace(guard,changed);
}

function setup(source,language,disableBlur) {
  const document=createDocument(),prototype=Object.getPrototypeOf(document.createElement('div'));
  const simpleMatches=prototype.matches,oldFocus=prototype.focus;
  prototype.matches=function(selector) {
    if(selector.includes(' ')) {
      const last=selector.lastIndexOf(' ');
      return this.matches(selector.slice(last+1))&&!!this.parentElement?.closest(selector.slice(0,last));
    }
    const attr=selector.match(/^\[data-([\w-]+)(?:="([^"]*)")?\]$/);
    if(attr) {const key=attr[1].replace(/-([a-z])/g,(_,x)=>x.toUpperCase());return attr[2]===undefined?Object.hasOwn(this.dataset,key):this.dataset[key]===attr[2];}
    const idClass=selector.match(/^#([\w-]+)\.([\w-]+)$/);
    return idClass?this.id===idClass[1]&&this.classList.contains(idClass[2]):simpleMatches.call(this,selector);
  };
  prototype.addEventListener=function(type,fn){this.listeners??={};(this.listeners[type]??=[]).push(fn);};
  prototype.click=function(){if(!this.disabled)this.onclick?.({target:this,preventDefault(){}});if(!this.disabled)for(const fn of this.listeners?.click||[])fn({target:this});};
  prototype.before=function(node){this.parentElement.insertBefore(node,this);};
  prototype.focus=function(...args){const previous=document.activeElement;oldFocus.apply(this,args);if(previous!==document.activeElement)previous.onblur?.({target:previous});};
  if(disableBlur)Object.defineProperty(prototype,'disabled',{configurable:true,get(){return !!this._disabled;},set(value){this._disabled=value;if(value&&document.activeElement===this)this.blur();}});
  const names=['_invPlaceDetail','_invRenderDetail','_invClearHover','_invRestoreSelectedActions','_invCategoryMatches','_invChangeCategory','_invPlacement','_invPlacementChanged','renderInv','renderOssPanel','_ossHideBoneInfo','_bonePartName','_ossSetComplete','closePanel'];
  if(source.includes('function _invRenderEmptyDetail('))names.push('_invRenderEmptyDetail');
  const metrics={renderInv:0,renderOssPanel:0},errors=[];
  const functions=names.map(name=>extractFunction(source,name)).join('\n')+`
    const actualInv=renderInv,actualOss=renderOssPanel;
    renderInv=(...args)=>{env.metrics.renderInv++;return actualInv(...args);};
    renderOssPanel=(...args)=>{env.metrics.renderOssPanel++;return actualOss(...args);};
    env._invChangeCategory=_invChangeCategory;env.renderOssPanel=renderOssPanel;`;
  const mount=document.createElement('main');document.body.appendChild(mount);
  // Host construction does not invoke the renderers; dependencies are populated before opening.
  const ui=createHost(document,mount,{factory:{current:sourceFactory(source)},functions:{current:functions}},'current',language);
  Object.assign(ui.env,{metrics,console:{error(...args){errors.push(args.map(String).join(' '));}},ANC_ROSTER:[{id:'iron_warlord',ko:'철갑 전대',en:'Iron Warlord'}],_BONE_PARTS:['skull','torso','arms','legs'],_BONE_PART_KO:{skull:'두개골',torso:'몸통',arms:'팔',legs:'다리'},_BONE_PART_EN:{skull:'Skull',torso:'Torso',arms:'Arms',legs:'Legs'}});
  const wrap=ui.panel.querySelector('.inv-wrap'),equip=document.createElement('div');equip.className='inv-equip';wrap.appendChild(equip);equip.appendChild(ui.nodes.invEqGrid);
  for(const id of ['invOssuaryPanel','invCrystalsPanel','invStorageCol','invCenter','invStBagSection','optLang']){const node=document.createElement('div');node.id=id;ui.nodes[id]=node;wrap.appendChild(node);}ui.nodes.optLang.value=language;
  ui.env.INV.equipped.ossuary={slot:'ossuary',name:'Fixture urn',anc:'iron_warlord',rarity:0,el:0,socketCount:0};
  ui.env.INV.ossCollect={iron_warlord_skull:{r:2,t:1}};
  new Function('env',`with(env){${helpers}${inventory}inventory();translate();}`)(ui.env);
  ui.opener.onclick();
  const guard=source.split('\n').find(line=>line.includes("if(['Space','Enter','NumpadEnter','Tab'].includes(e.code)"));
  assert.ok(guard,'공용 panel keydown guard 존재');
  const route=new Function('e','Element',guard+'\nreturn "game-route";');
  ui.env.renderInv=ui.api.renderInv;
  const key=(node,code,extra={})=>{const event={target:node,code,prevented:false,defaultPrevented:false,preventDefault(){this.prevented=true;this.defaultPrevented=true;},stopPropagation(){},...extra};node.onkeydown?.(event);return event;};
  const up=(node,code,extra={})=>{const event={target:node,code,preventDefault(){},...extra};node.onkeyup?.(event);return event;};
  return {...ui,document,metrics,errors,names,guard,key,up,route:event=>route(event,document.createElement('div').constructor),
    filter(key,val){return [...ui.nodes.invFilters.querySelectorAll('button')].find(n=>n.dataset.inventoryFilterKey===key&&n.dataset.inventoryFilterValue===String(val));},
    card(){return ui.nodes.invGrid.querySelector('.inv-item');},
    switchPage(page){const tab=document.getElementById('inventory-tab-'+page);tab.focus();tab.click();return tab;},
    tabKey(tab,key){for(const fn of tab.listeners?.keydown||[])fn({target:tab,key,preventDefault(){},stopPropagation(){}});}
  };
}

function check(name,fn){try{const detail=fn();results.push({name,pass:true,detail});}catch(error){results.push({name,pass:false,error:error.stack.replace(/data:text\/javascript;base64,[A-Za-z0-9+/=]+/g,'embedded-fixture')});}}
for(const path of ['game.html','game-easy-test.html']) {
  const original=fs.readFileSync(new URL(path,root),'utf8'),source=candidate?patched(original):original;
  sourceRecords[path]={productionSha256:sha(original),testedSha256:sha(source),factorySha256:sha(sourceFactory(source)),functions:{}};
  for(const language of ['ko','en'])for(const blur of [false,true]) {
    const tag=`${path}/${language}/${blur?'blur':'retain'}`;
    check(tag+' filter→disabled take/remove→bag keyboard→close',()=>{
      const ui=setup(source,language,blur),{document,nodes,env}=ui;
      for(const name of ui.names){const text=extractFunction(source,name);sourceRecords[path].functions[name]={sha256:sha(text),line:source.slice(0,source.indexOf('function '+name+'(')).split('\n').length};}
      const trace=[];
      ui.switchPage('ossuary');
      let filter=ui.filter('rarity',0);filter.focus();const original=filter;filter.click();filter=ui.filter('rarity',0);
      assert.notEqual(filter,original);assert.equal(original.isConnected,false);assert.equal(document.activeElement,filter);assert.equal(filter.attrs['aria-pressed'],'true');trace.push('filter:new same key/value');
      nodes.invOssuaryPanel.querySelector('[data-part="skull"]').click();
      const take=nodes.invOssuaryPanel.querySelector('.oss-withdraw');take.focus();assert.equal(ui.route({target:take,code:'Space'}),undefined);
      delete env.INV.ossCollect.iron_warlord_skull;ui.api.renderInv();
      assert.equal(take.disabled,true);assert.equal(document.activeElement,nodes.invClose);trace.push('take disabled:close');
      const remove=nodes.invOssuaryPanel.querySelector('.oss-unequip');remove.focus();env.INV.equipped.ossuary=null;ui.api.renderInv();
      assert.equal(remove.disabled,true);assert.equal(document.activeElement,nodes.invClose);trace.push('remove disabled:close');
      // Invoke the actual tabBar keyboard listener: ArrowLeft ossuary→equipment.
      const tab=document.getElementById('inventory-tab-ossuary');tab.focus();ui.tabKey(tab,'ArrowLeft');
      assert.equal(ui.panel.dataset.inventoryPage,'equipment');assert.equal(document.activeElement,document.getElementById('inventory-tab-equipment'));
      assert.equal(nodes.invOssuaryPanel.attrs['aria-hidden'],'true');assert.equal(nodes.invRight.parentElement.className,'inv-wrap');
      const card=ui.card();assert.ok(card);card.focus();assert.equal(ui.route({target:card,code:'Enter'}),undefined);const event=ui.key(card,'Enter');
      assert.equal(card.isConnected,false,'actual renderInv removes the original key target');
      assert.equal(event.prevented,true);assert.equal(ui.route(event),undefined);assert.equal(document.activeElement,nodes.invRight);assert.equal(env.INV.bag[env.INV.selected],ui.item);assert.ok(nodes.invRight.querySelector('.item-detail').innerHTML.includes(ui.item.name));trace.push('bag Enter:detail');
      const detail=nodes.invRight;ui.api._invClearHover();assert.equal(document.activeElement,detail);assert.equal(detail.style.visibility,'visible');
      ui.api.renderInv();assert.ok(document.activeElement.isConnected);assert.equal(document.activeElement,detail);assert.equal(env.INV.bag[env.INV.selected],ui.item);
      const current=ui.card();current.focus();const tabEvent=ui.key(current,'Tab');assert.equal(tabEvent.prevented,false);assert.equal(ui.route(tabEvent),undefined);
      ui.key(current,'Space');assert.equal(document.activeElement,current);ui.up(current,'Space');assert.equal(document.activeElement,detail);
      ui.api.closePanel('invPanel');assert.equal(document.activeElement,ui.opener);trace.push('close:external opener');
      assert.equal(ui.route({target:ui.opener,code:'Space'}),'game-route');assert.equal(ui.route({target:ui.opener,code:'KeyF',defaultPrevented:true}),'game-route');assert.deepEqual(ui.errors,[]);assert.ok(ui.metrics.renderInv>=8&&ui.metrics.renderOssPanel>=8);
      return {trace,actualCalls:ui.metrics};
    });
    check(tag+' interleaved rerender/Space cancellation/external ownership',()=>{
      const ui=setup(source,language,blur),{document,nodes,env}=ui;
      ui.switchPage('ossuary');
      const filter=ui.filter('rarity',4);filter.focus();filter.click();assert.equal(ui.card(),null);assert.equal(document.activeElement,ui.filter('rarity',4));
      ui.filter('rarity',4).click();assert.equal(document.activeElement,ui.filter('rarity',4));assert.equal(ui.filter('rarity',4).attrs['aria-pressed'],'false');
      nodes.invOssuaryPanel.querySelector('[data-part="skull"]').click();
      const external=document.createElement('button');external.id='external-owner';document.body.appendChild(external);external.focus();
      delete env.INV.ossCollect.iron_warlord_skull;env.INV.equipped.ossuary=null;ui.api.renderInv();assert.equal(document.activeElement,external);
      ui.switchPage('equipment');const old=ui.card();old.focus();ui.key(old,'Space');
      ui.switchPage('ossuary');ui.switchPage('equipment');const current=ui.card();current.focus();ui.up(current,'Space');assert.equal(document.activeElement,current);assert.equal(env.INV.selected,null);
      const before=ui.metrics.renderInv;ui.key(current,'Enter',{ctrlKey:true});ui.key(current,'Enter',{repeat:true});assert.equal(ui.metrics.renderInv,before);
      const entered=ui.key(current,'NumpadEnter');assert.equal(entered.prevented,true);assert.equal(ui.route(entered),undefined);assert.equal(document.activeElement,nodes.invRight);
      ui.api.closePanel('invPanel');assert.equal(document.activeElement,ui.opener);ui.api.renderInv();assert.equal(document.activeElement,ui.opener);
      assert.deepEqual(ui.errors,[]);return {actualCalls:ui.metrics,spaceAcrossNewCard:'no activation',externalFocus:'preserved'};
    });
  }
}
const report={task:'cross-panel-focus-source',mode:candidate?'unapplied-candidate':'current-production',startedAt,finishedAt:new Date().toISOString(),head:spawnSync('git',['rev-parse','HEAD'],{cwd:fileURLToPath(root),encoding:'utf8'}).stdout.trim(),sources:sourceRecords,compositionSha256:sha(composition),passed:results.filter(row=>row.pass).length,failed:results.filter(row=>!row.pass).length,results,limits:['Node DOM synthetic retain/blur/focus; no native events/layout/gamepad','Actual renderInv/renderOssPanel/factory/card/tab handlers; global keyboard guard only, not whole listener','Synthetic bone/ossuary state deletion; no real withdrawal/economy/save/portrait/image loading','Inherited item sizing/stats/storage/crystals/art/comparison stubs; no whole-game execution']};
process.stdout.write(JSON.stringify(report,null,2)+'\n');process.exitCode=report.failed?1:0;
